import{_ as t,c as s,o as r,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"易雅原序","description":"周易辑闻 - 易雅原序","frontmatter":{"title":"易雅原序","description":"周易辑闻 - 易雅原序"},"headers":[],"relativePath":"zh/classics/jiwen/008.md","filePath":"zh/classics/jiwen/008.md"}'),i={name:"zh/classics/jiwen/008.md"};function c(o,a,l,d,p,m){return r(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易雅原序",tabindex:"-1"},[n("易雅原序 "),e("a",{class:"header-anchor",href:"#易雅原序","aria-label":"Permalink to “易雅原序”"},"​")],-1),e("p",null,"尔雅，训诂之书也。目张而汇聚，读之事义物理秩然在前。富哉书也，经之翼乎！厥后广雅、博雅、埤雅，虽依放为书，大槩于道无所益。易雅之作，则异于是。易，变易也。卦殊其义，爻异其旨，万变毕陈，众理丛载。学者如乍入清庙，目衒于尊彝币玉，体烦于升降盥奠，耳乱于钟鼓磬箫。凡礼之文，乐之节，且不暇品名，况能因之以知其实乎？又若泛沧海而罔识乡往之方，游建章而不知出入之会。汝梅尝病焉，乃复熟画辞而为此书，庶几缘是指入易之迷津，求体易之实用。或曰：「子何沈锢辞画，不能融浑希微若是哉？」余曰：「程子论为学之害曰：昔之害，乘其迷暗；今之害，因其高明。自谓之穷神知化，实则不足以开物成务；言为无不周徧，实则外於伦理。嗟夫！浅深非二水，体用非二物，精粗无二理也。易之为书，言近而指远，不知言何以知其指？通乎近，则远固在是，傥慕远而失诸近，吾知两失之而已尔。世或外辞画以求易，则此书为赘，否则不易吾言矣。程子之论，真为学之大闲欤！」汴水赵汝梅叙。易雅原序。",-1)])])}const h=t(i,[["render",c]]);export{f as __pageData,h as default};
